// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    function testFuzz_property(bytes calldata data) public {
        Reverter r = new Reverter();
        bool ok = true;
        try c.forward(address(r), data) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: forwarding to a callee that reverts must revert forward too.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
